                if min_index < lookback:
                    i = min_index + lookback
                else:
                    i = min_index
            rows = numpy.arange(i, min(i + batch_size, max_index))
            i += len(rows)
        samples = numpy.zeros((len(rows), lookback // step, data.shape[-1] - len(target)))
        targets = numpy.zeros((len(rows), len(target)))
