def forecast_holt_winters(group_df):
    x = group_df.copy()
    if x['sales'].notna().sum() > 30:
        try:
            sales_log = numpy.log1p(x['sales'].dropna())
            model = statsmodels.tsa.holtwinters.ExponentialSmoothing(sales_log, trend='add', seasonal='add', seasonal_periods=7).fit(optimized=True)
            forecast_len = x['sales'].isna().sum()
            if forecast_len > 0:
                forecast_log = model.forecast(forecast_len)
                x.loc[x['sales'].isna(), 'sales'] = numpy.expm1(forecast_log).clip(lower=0).values
            return x
        except:
            x['sales'] = x['sales'].bfill().ffill()
            return x
    else:
        x['sales'] = x['sales'].bfill().ffill()
        return x

